  'SPC-WIZ-030': { id: 'SPC-WIZ-030', screen: '명세서 · 위저드 공통 프레임', component: '단계 안내(AI 메시지)', display: '각 단계 상단: 단계명 + 이 단계에서 할 일 1~2문장(예: 구성요소 — "구성요소의 명칭·정의를 확인하고 순서를 정한 뒤 부호(100, 200…)를 부여하세요. 채택한 구성요소가 청구항의 기준이 됩니다.") · ① 직후 업로드하신 문서를 분석했습니다. 발명의 설명 항목을 분석합니다.', interaction: '정독', precondition: '단계 도달', postcondition: '—' },
  'SPC-WIZ-040': { id: 'SPC-WIZ-040', screen: '명세서 · 위저드 공통 프레임', component: '확정 단계 접힘 요약 (영역)', display: '초록 ✓ + 단계명 + 1줄 요약(예: 제안기술 4/4 · 종래기술 2/2 항목 채택, 관련 이미지 2/2개 선택, 구성요소 4개 확정, 명세서 도면 2개 (도 1~2), 독립항 세트 · 종속항 확정, 7개 섹션)', interaction: '↓ 액션별', precondition: '단계 확정됨', postcondition: '—' },
  'SPC-WIZ-041': { id: 'SPC-WIZ-041', screen: '명세서 · 위저드 공통 프레임', component: '펼치기 / 접기', display: '버튼', interaction: '클릭', precondition: '확정 단계', postcondition: '내용 열람(읽기 전용·흐림) / 재접힘' },
