  'SPC-AST-050': { id: 'SPC-AST-050', screen: '명세서 · AI 어시스턴트 — 작성 안내', component: '질문 입력창', display: '"단계 진행·작성 방법을 질문하세요..." + 전송', interaction: '입력·Enter', precondition: '입력 비어 있지 않음', postcondition: '0.5초 후 응답' },
  'SPC-EDT-060': { id: 'SPC-EDT-060', screen: '명세서 · 에디터', component: '편집 툴바 (영역)', display: '한 줄 · 편집 도구만(화면 이동은 내비게이션 행). 좌: 실행 취소·다시 실행 ｜ ∑ 수식 ｜ 찾기 · 힌트 "단락을 클릭하면 수식을 삽입할 수 있습니다"(미편집 시, xl 이상) · 우: 미리보기·DOCX·PDF', interaction: '↓ 액션별', precondition: '에디터 진입', postcondition: '—' },
